//@ ensures [f]pointers(program->_builtin_class_ids, Program_BUILTIN_CLASS_IDS_COUNT, ws) &*& [g]class_bits_table(program, cbits) &*& result == 0 ? builtin_classes_ok(ws, cbits) == true : true;
{
  char *error = builtin_class_error(program, Program_string_class_id(program), (int)STRING_TAG, 0);
  if (error == 0) {
    error = builtin_class_error(program, Program_array_class_id(program), (int)ARRAY_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_byte_array_class_id(program), (int)BYTE_ARRAY_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_byte_array_cow_class_id(program), (int)INSTANCE_TAG, (int)(Instance_BYTE_ARRAY_COW_IS_MUTABLE_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_byte_array_slice_class_id(program), (int)INSTANCE_TAG, (int)(Instance_BYTE_ARRAY_SLICE_TO_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_string_slice_class_id(program), (int)INSTANCE_TAG, (int)(Instance_STRING_SLICE_TO_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_string_byte_slice_class_id(program), (int)INSTANCE_TAG, (int)(Instance_STRING_BYTE_SLICE_TO_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_list_class_id(program), (int)INSTANCE_TAG, (int)(Instance_LIST_SIZE_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_list_slice_class_id(program), (int)INSTANCE_TAG, (int)(Instance_LIST_SLICE_TO_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_map_class_id(program), (int)INSTANCE_TAG, (int)(Instance_MAP_BACKING_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_tombstone_class_id(program), (int)INSTANCE_TAG, (int)(Instance_TOMBSTONE_DISTANCE_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_stack_class_id(program), (int)STACK_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_null_class_id(program), (int)ODDBALL_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_true_class_id(program), (int)ODDBALL_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_false_class_id(program), (int)ODDBALL_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_object_class_id(program), (int)INSTANCE_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_double_class_id(program), (int)DOUBLE_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_large_integer_class_id(program), (int)LARGE_INTEGER_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_smi_class_id(program), (int)INSTANCE_TAG, 0);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_task_class_id(program), (int)TASK_TAG, 2);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_large_array_class_id(program), (int)INSTANCE_TAG, (int)(Instance_LARGE_ARRAY_VECTOR_INDEX + 1));
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_lazy_initializer_class_id(program), (int)INSTANCE_TAG, 1);
  }
  if (error == 0) {
    error = builtin_class_error(program, Program_exception_class_id(program), (int)INSTANCE_TAG, 2);
  }
  return error;
}

